-- Arabic descriptions for products that have none yet (never overwrites admin edits).
with ar(name, body) as (values
('Yirgacheffe', E'تفاصيل القهوة\n\n* الحموضة: مشرقة\n* الحلاوة: متوسطة\n* القوام: حريري\n\nلمحة النكهة: حمضيات وأزهار\n\nمعلومات إضافية\n\n* المنشأ: إثيوبيا\n* المنطقة: يرغاتشيفي\n* طريقة المعالجة: مغسولة\n* ملاحظات التذوق: برغموت – ليمون – عسل – أزهار\n* التقييم: 88\n* الارتفاع: 1,900–2,200 م\n* الصنف: هيرلوم\n\nوصف المحمصة\n\n«قهوة أنيقة وعطرية — كوب إثيوبي مميز بحمضيات متألقة ونهاية زهرية نظيفة. مثالية للتقطير اليدوي.»'),
('Colombia', E'تفاصيل القهوة\n\n* الحموضة: متوسطة\n* الحلاوة: عالية\n* القوام: متوسط إلى ممتلئ\n\nلمحة النكهة: حلوة ومتوازنة\n\nمعلومات إضافية\n\n* المنشأ: كولومبيا\n* المنطقة: هويلا\n* طريقة المعالجة: مغسولة\n* ملاحظات التذوق: كراميل – تفاح أحمر – كاكاو – مكسرات\n* التقييم: 85\n* الارتفاع: 1,500–1,900 م\n* الصنف: كاتورا / كاستيو\n\nوصف المحمصة\n\n«تحميص كولومبي كلاسيكي متوازن — حلاوة الكراميل مع فاكهة ناعمة ونهاية كاكاو دافئة. رفيق يومي ممتاز.»'),
('Brazil Cerrado', E'تفاصيل القهوة\n\n* الحموضة: منخفضة\n* الحلاوة: عالية\n* القوام: كريمي\n\nلمحة النكهة: شوكولاتة ومكسرات\n\nمعلومات إضافية\n\n* المنشأ: البرازيل\n* المنطقة: سيرادو مينيرو\n* طريقة المعالجة: طبيعية\n* ملاحظات التذوق: شوكولاتة – بندق – سكر بني\n* التقييم: 84\n* الارتفاع: 900–1,200 م\n* الصنف: بوربون أصفر\n\nوصف المحمصة\n\n«ناعمة وغنية بالشوكولاتة مع حموضة منخفضة — مثالية للإسبريسو ومشروبات الحليب ولمحبي الكوب الأغنى.»'),
('Kenya AA', E'تفاصيل القهوة\n\n* الحموضة: عالية\n* الحلاوة: متوسطة\n* القوام: عصيري\n\nلمحة النكهة: توت جريء وحمضيات\n\nمعلومات إضافية\n\n* المنشأ: كينيا\n* المنطقة: نييري\n* طريقة المعالجة: مغسولة\n* ملاحظات التذوق: كشمش أسود – طماطم – جريب فروت – سكر بني\n* التقييم: 89\n* الارتفاع: 1,700–1,900 م\n* الصنف: SL28 / SL34\n\nوصف المحمصة\n\n«قهوة كينية AA نابضة ومعقدة بإشراقة الكشمش الأسود المميزة. الأفضل كقهوة مقطرة لمحبي الحموضة الحيوية.»'),
('Signature Drip Box', E'أكياس دريب جاهزة للتحضير من خلطتنا الخاصة.\n\n* العبوة: 10 أكياس\n* التحميص: متوسط\n* وقت التحضير: حوالي 3 دقائق\n* ملاحظات التذوق: عسل – برتقال – كاكاو ناعم\n\nلا تحتاج أي أدوات — فقط ماء ساخن وكوب. حلاوة متوازنة لصباحاتك اليومية.'),
('Dark Roast Drip Box', E'أكياس دريب فردية جريئة لكوب أعمق.\n\n* العبوة: 10 أكياس\n* التحميص: داكن\n* وقت التحضير: حوالي 3 دقائق\n* ملاحظات التذوق: شوكولاتة داكنة – دبس – دخان\n\nغنية ودافئة — مثالية بعد الوجبات أو لمن يفضل القوة.'),
('Ethiopia Drip Pack', E'أكياس دريب إثيوبية بتحميص فاتح تبرز صفاء النكهات الزهرية.\n\n* العبوة: 8 أكياس\n* التحميص: فاتح\n* المنشأ: إثيوبيا\n* ملاحظات التذوق: ياسمين – خوخ – برغموت\n\nطابع القهوة المختصة المقطرة بصيغة سهلة الحمل.'),
('Colombia Drip Pack', E'أكياس دريب كولومبية حلوة لكوب متوازن في منتصف اليوم.\n\n* العبوة: 8 أكياس\n* التحميص: متوسط\n* المنشأ: كولومبيا\n* ملاحظات التذوق: كراميل – تفاح – كاكاو\n\nناعمة وسهلة ومناسبة للسفر.'),
('Pour-Over Kettle', E'غلاية ستانلس ستيل بعنق مقوس للتحكم الدقيق في التقطير اليدوي.\n\n* السعة: 1.0 لتر\n* المادة: ستانلس ستيل مصقول\n* الفوهة: عنق إوزي ضيق\n\nمصممة لتشبع متساوٍ وتحضير مقطر ثابت في المنزل.'),
('Manual Coffee Grinder', E'مطحنة يدوية بشفرات سيراميك قابلة للضبط من الإسبريسو إلى الفرنش برس.\n\n* الشفرات: سيراميك مخروطية\n* درجة الطحن: ناعم ← خشن\n* الهيكل: معدني محمول\n\nبن طازج في كل كوب — صغيرة بما يكفي للسفر.'),
('Ceramic Pour-Over Dripper', E'قمع تقطير سيراميك على شكل V يحتفظ بالحرارة لاستخلاص أنقى.\n\n* الحجم: 1–2 كوب\n* المادة: سيراميك مزجج\n* متوافق مع: فلاتر المخروط القياسية\n\nأداة تحضير بسيطة ومتينة للقهوة المقطرة اليومية.'),
('Brew Scale', E'ميزان رقمي صغير بدقة 0.1 غ مع مؤقت مدمج.\n\n* الدقة: 0.1 غ\n* السعة: 2 كغ\n* المزايا: مؤقت، تصفير، شحن USB\n\nاضبط النسب للتقطير اليدوي والإسبريسو والتحضير بالكميات.'),
('Paper Filters (100 pcs)', E'فلاتر مخروطية مبيضة بالأكسجين لتقطير نقي بدون طعم الورق.\n\n* العدد: 100 فلتر\n* الشكل: مخروطي / متوافق مع V60\n* المعالجة: مبيضة بالأكسجين\n\nخزّن ما يكفيك للتحضير اليومي بدون طعم الكرتون.')
)
update public.products p set description_ar = ar.body
from ar where p.name = ar.name and coalesce(trim(p.description_ar), '') = '';

update public.products
set description_ar = replace(description_ar, '* الروائح العطرية:', '* ملاحظات التذوق:')
where description_ar like '%* الروائح العطرية:%';
